#include "profile_manager.h"
#include <stdio.h>
#include <string.h>
static void copy(char *d,size_t cap,const char *s){size_t n;if(!s)s="";n=strlen(s);if(n>=cap)n=cap-1;memcpy(d,s,n);d[n]='\0';}
void rtp_profile_manager_init(rtp_profile_manager *m,rtp_preferences_ui *n,rtp_preferences *p,rtp_profile_store *s){if(!m)return;memset(m,0,sizeof(*m));m->navigation=n;m->preferences=p;m->profiles=s;m->page=RTP_PM_PAGE_SETTINGS;}
int rtp_profile_manager_open(rtp_profile_manager *m){if(!m||!m->navigation||!m->preferences||!m->profiles)return RTP_PM_INVALID_ARGUMENT;m->page=RTP_PM_PAGE_PROFILES;m->selected_profile_id[0]=0;m->pending_delete_id[0]=0;return RTP_PM_OK;}
int rtp_profile_manager_back(rtp_profile_manager *m){if(!m)return RTP_PM_INVALID_ARGUMENT;if(m->page==RTP_PM_PAGE_CONFIRM_DELETE){m->pending_delete_id[0]=0;m->page=RTP_PM_PAGE_PROFILE_ACTIONS;return RTP_PM_OK;}if(m->page==RTP_PM_PAGE_PROFILE_ACTIONS){m->page=RTP_PM_PAGE_PROFILES;return RTP_PM_OK;}if(m->page==RTP_PM_PAGE_PROFILES){m->page=RTP_PM_PAGE_SETTINGS;return RTP_PM_OK;}return RTP_PM_NOT_FOUND;}
int rtp_profile_manager_build_view(const rtp_profile_manager *m,rtp_pm_view *v){size_t i;if(!m||!v||!m->profiles)return RTP_PM_INVALID_ARGUMENT;memset(v,0,sizeof(*v));v->page=m->page;switch(m->page){case RTP_PM_PAGE_PROFILES:copy(v->title,sizeof(v->title),"Layout Profiles");for(i=0;i<m->profiles->count&&i<RTP_PROFILE_MAX;i++){const rtp_layout_profile *p=&m->profiles->profiles[i];rtp_pm_row *r=&v->rows[v->count];copy(r->id,sizeof(r->id),p->id);copy(r->title,sizeof(r->title),p->name);r->kind=RTP_PM_ROW_PROFILE;r->selected=!strcmp(p->id,m->selected_profile_id);if(r->selected)v->selected_index=v->count;v->count++;}if(v->count<RTP_PM_MAX_ROWS){rtp_pm_row *r=&v->rows[v->count++];copy(r->id,sizeof(r->id),"create-profile");copy(r->title,sizeof(r->title),"Create profile");r->kind=RTP_PM_ROW_CREATE;}break;case RTP_PM_PAGE_PROFILE_ACTIONS:copy(v->title,sizeof(v->title),"Profile Options");copy(v->selected_profile_id,sizeof(v->selected_profile_id),m->selected_profile_id);{const char *labels[]={"Apply profile","Update from current layout","Rename profile","Delete profile"};const rtp_pm_row_kind kinds[]={RTP_PM_ROW_APPLY,RTP_PM_ROW_UPDATE,RTP_PM_ROW_RENAME,RTP_PM_ROW_DELETE};for(i=0;i<4;i++){rtp_pm_row *r=&v->rows[v->count++];snprintf(r->id,sizeof(r->id),"profile-action-%u",(unsigned)i);copy(r->title,sizeof(r->title),labels[i]);r->kind=kinds[i];}}break;case RTP_PM_PAGE_CONFIRM_DELETE:copy(v->title,sizeof(v->title),"Confirm profile deletion");{rtp_pm_row *r=&v->rows[v->count++];copy(r->id,sizeof(r->id),"confirm-delete");copy(r->title,sizeof(r->title),"Delete permanently");r->kind=RTP_PM_ROW_CONFIRM;r=&v->rows[v->count++];copy(r->id,sizeof(r->id),"cancel-delete");copy(r->title,sizeof(r->title),"Cancel");r->kind=RTP_PM_ROW_CANCEL;}break;default:copy(v->title,sizeof(v->title),"Rt:Settings Extended");break;}return RTP_PM_OK;}
int rtp_profile_manager_select(rtp_profile_manager *m,const char *id){if(!m||!id||m->page!=RTP_PM_PAGE_PROFILES)return RTP_PM_INVALID_ARGUMENT;if(!rtp_profiles_find(m->profiles,id))return RTP_PM_NOT_FOUND;copy(m->selected_profile_id,sizeof(m->selected_profile_id),id);m->page=RTP_PM_PAGE_PROFILE_ACTIONS;return RTP_PM_OK;}
int rtp_profile_manager_create(rtp_profile_manager *m,const char *id,const char *name){if(!m||!id||!name||m->page!=RTP_PM_PAGE_PROFILES)return RTP_PM_INVALID_ARGUMENT;return rtp_profiles_create(m->profiles,id,name,m->preferences)==RTP_PROFILE_OK?RTP_PM_OK:RTP_PM_PROFILE_ERROR;}
int rtp_profile_manager_apply(rtp_profile_manager *m){if(!m||m->page!=RTP_PM_PAGE_PROFILE_ACTIONS)return RTP_PM_INVALID_ARGUMENT;if(rtp_profiles_apply(m->profiles,m->selected_profile_id,m->preferences)!=RTP_PROFILE_OK)return RTP_PM_PROFILE_ERROR;rtp_preferences_ui_init(m->navigation);m->page=RTP_PM_PAGE_PROFILES;return RTP_PM_OK;}
int rtp_profile_manager_update(rtp_profile_manager *m){if(!m||m->page!=RTP_PM_PAGE_PROFILE_ACTIONS)return RTP_PM_INVALID_ARGUMENT;return rtp_profiles_update(m->profiles,m->selected_profile_id,m->preferences)==RTP_PROFILE_OK?RTP_PM_OK:RTP_PM_PROFILE_ERROR;}
int rtp_profile_manager_rename(rtp_profile_manager *m,const char *name){if(!m||!name||m->page!=RTP_PM_PAGE_PROFILE_ACTIONS)return RTP_PM_INVALID_ARGUMENT;return rtp_profiles_rename(m->profiles,m->selected_profile_id,name)==RTP_PROFILE_OK?RTP_PM_OK:RTP_PM_PROFILE_ERROR;}
int rtp_profile_manager_request_delete(rtp_profile_manager *m){if(!m||m->page!=RTP_PM_PAGE_PROFILE_ACTIONS)return RTP_PM_INVALID_ARGUMENT;copy(m->pending_delete_id,sizeof(m->pending_delete_id),m->selected_profile_id);m->page=RTP_PM_PAGE_CONFIRM_DELETE;return RTP_PM_OK;}
int rtp_profile_manager_confirm_delete(rtp_profile_manager *m,int confirmed){if(!m||m->page!=RTP_PM_PAGE_CONFIRM_DELETE)return RTP_PM_INVALID_ARGUMENT;if(!confirmed){m->pending_delete_id[0]=0;m->page=RTP_PM_PAGE_PROFILE_ACTIONS;return RTP_PM_OK;}if(rtp_profiles_delete(m->profiles,m->pending_delete_id)!=RTP_PROFILE_OK)return RTP_PM_PROFILE_ERROR;m->pending_delete_id[0]=0;m->selected_profile_id[0]=0;m->page=RTP_PM_PAGE_PROFILES;return RTP_PM_OK;}
